import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    heights = list(map(int, data[1:]))

    if n == 1:
        print(1)
        print(heights[0])
        return

    # Dictionary to store the last occurrence of each height
    last_occurrence = {}

    # Arrays to store the length of the longest increasing and decreasing subsequences ending at each index
    inc = [1] * n
    dec = [1] * n

    # Fill the inc and dec arrays
    for i in range(n):
        if i > 0 and heights[i] == heights[i - 1]:
            inc[i] = inc[i - 1] + 1
            dec[i] = dec[i - 1] + 1
        elif i > 0 and heights[i] == heights[i - 1] + 1:
            inc[i] = dec[i - 1] + 1
            dec[i] = inc[i - 1]
        elif i > 0 and heights[i] == heights[i - 1] - 1:
            inc[i] = inc[i - 1]
            dec[i] = dec[i - 1] + 1

        if heights[i] in last_occurrence:
            inc[i] = max(inc[i], inc[last_occurrence[heights[i]]] + 1)
            dec[i] = max(dec[i], dec[last_occurrence[heights[i]]] + 1)

        last_occurrence[heights[i]] = i

    # Find the maximum length of the balanced circle
    max_length = 0
    for i in range(n):
        max_length = max(max_length, inc[i] + dec[i] - 1)

    # Reconstruct the maximum balanced circle
    result = []
    for i in range(n):
        if inc[i] + dec[i] - 1 == max_length:
            start = i
            break

    current_height = heights[start]
    while True:
        result.append(current_height)
        found = False
        for j in range(start - 1, -1, -1):
            if abs(heights[j] - current_height) <= 1:
                current_height = heights[j]
                start = j
                found = True
                break
        if not found:
            break

    # If we didn't complete the circle, continue from the end
    if len(result) < max_length:
        current_height = heights[start]
        for j in range(start + 1, n):
            if abs(heights[j] - current_height) <= 1:
                current_height = heights[j]
                result.append(current_height)
            else:
                break

    # Ensure the circle is closed
    if result[0] != result[-1]:
        result.append(result[0])

    print(max_length)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
